-- 틀을 만든다

public abstract class AbstractTemplate<T> {

    private final LogTrace trace;

    protected AbstractTemplate(LogTrace trace) { this.trace = trace; }

    public final T execute(String message) {      // final 이다
        TraceStatus status = null;
        try {
            status = trace.begin(message);
            T result = call();                    // 구멍
            trace.end(status);
            return result;
        } catch (Exception e) {
            trace.exception(status, e);
            throw e;
        }
    }

    protected abstract T call();
}

